mapper.select:
SELECT COUNT(*) AS total, SUM(CASE WHEN assessment_type = 'safety' THEN 1 ELSE 0 END) AS safety, SUM(CASE WHEN assessment_type = 'site' THEN 1 ELSE 0 END) AS site, SUM(CASE WHEN assessment_type = 'process' THEN 1 ELSE 0 END) AS process FROM assessment_record WHERE is_deleted = 0
AND assessment_date BETWEEN #{startDate} AND #{endDate}
AND YEAR(assessment_date) = YEAR(CURDATE()) AND MONTH(assessment_date) = MONTH(CURDATE())

SELECT CASE WHEN assessment_type = 'safety' THEN '安全考核' WHEN assessment_type = 'site' THEN '现场考核' WHEN assessment_type = 'process' THEN '工艺考核' ELSE assessment_type END AS name, COUNT(*) AS value, CONCAT(ROUND(COUNT(*) * 100.0 / ( SELECT COUNT(*) FROM assessment_record WHERE is_deleted = 0
AND assessment_date BETWEEN #{startDate} AND #{endDate}
AND YEAR(assessment_date) = YEAR(CURDATE()) AND MONTH(assessment_date) = MONTH(CURDATE())
), 1), '%') AS percentage FROM assessment_record WHERE is_deleted = 0
AND assessment_date BETWEEN #{startDate} AND #{endDate}
AND YEAR(assessment_date) = YEAR(CURDATE()) AND MONTH(assessment_date) = MONTH(CURDATE())
GROUP BY assessment_type ORDER BY value DESC

SELECT shift, COUNT(*) AS count, CONCAT(ROUND(COUNT(*) * 100.0 / ( SELECT COUNT(*) FROM assessment_record WHERE is_deleted = 0
AND assessment_date BETWEEN #{startDate} AND #{endDate}
AND YEAR(assessment_date) = YEAR(CURDATE()) AND MONTH(assessment_date) = MONTH(CURDATE())
), 1), '%') AS rate FROM assessment_record WHERE is_deleted = 0
AND assessment_date BETWEEN #{startDate} AND #{endDate}
AND YEAR(assessment_date) = YEAR(CURDATE()) AND MONTH(assessment_date) = MONTH(CURDATE())
GROUP BY shift ORDER BY count DESC
